import { useState } from 'react';
import { __ } from '@wordpress/i18n';

import Button from '../../components/Button';
import { Field, TextInput, Checkbox } from '../../components/Input';

const PRESETS = [
	{ code: 'es', locale: 'es_ES', name: 'Spanish', native_name: 'Español' },
	{ code: 'fr', locale: 'fr_FR', name: 'French', native_name: 'Français' },
	{ code: 'de', locale: 'de_DE', name: 'German', native_name: 'Deutsch' },
	{ code: 'it', locale: 'it_IT', name: 'Italian', native_name: 'Italiano' },
	{ code: 'pt-br', locale: 'pt_BR', name: 'Portuguese (Brazil)', native_name: 'Português' },
	{ code: 'ja', locale: 'ja', name: 'Japanese', native_name: '日本語' },
	{ code: 'zh-cn', locale: 'zh_CN', name: 'Chinese (Simplified)', native_name: '简体中文' },
	{ code: 'ar', locale: 'ar', name: 'Arabic', native_name: 'العربية', is_rtl: true },
	{ code: 'hi', locale: 'hi_IN', name: 'Hindi', native_name: 'हिन्दी' },
	{ code: 'bn', locale: 'bn_BD', name: 'Bengali', native_name: 'বাংলা' },
];

export default function LanguageForm({ initial, onSubmit, onCancel, busy }) {
	const [values, setValues] = useState(() => ({
		code: initial?.code || '',
		locale: initial?.locale || '',
		name: initial?.name || '',
		native_name: initial?.native_name || '',
		flag: initial?.flag || '',
		is_rtl: !!initial?.is_rtl,
		active: initial?.active ?? true,
		position: initial?.position ?? 10,
		country_codes: Array.isArray(initial?.country_codes) ? initial.country_codes : [],
	}));
	const [countryDraft, setCountryDraft] = useState('');

	const set = (key) => (e) =>
		setValues((v) => ({ ...v, [key]: e.target.type === 'checkbox' ? e.target.checked : e.target.value }));

	const applyPreset = (preset) => {
		setValues((v) => ({
			...v,
			code: preset.code,
			locale: preset.locale,
			name: preset.name,
			native_name: preset.native_name,
			flag: preset.code,
			is_rtl: !!preset.is_rtl,
		}));
	};

	const addCountry = () => {
		const next = countryDraft.trim().toUpperCase();
		if (!/^[A-Z]{2}$/.test(next)) return;
		setValues((v) =>
			v.country_codes.includes(next) ? v : { ...v, country_codes: [...v.country_codes, next] }
		);
		setCountryDraft('');
	};

	const removeCountry = (code) =>
		setValues((v) => ({ ...v, country_codes: v.country_codes.filter((c) => c !== code) }));

	const submit = (e) => {
		e.preventDefault();
		onSubmit(values);
	};

	return (
		<form onSubmit={submit} className="ztrans-flex ztrans-flex-col ztrans-gap-4">
			{!initial && (
				<div>
					<div className="ztrans-mb-2 ztrans-text-xs ztrans-font-medium ztrans-text-gray-700">
						{__('Pick a preset (optional)', 'zentranslate')}
					</div>
					<div className="ztrans-flex ztrans-flex-wrap ztrans-gap-2">
						{PRESETS.map((p) => (
							<button
								key={p.code}
								type="button"
								onClick={() => applyPreset(p)}
								className="ztrans-bare ztrans-rounded-full ztrans-border ztrans-border-ztrans-border ztrans-bg-white ztrans-px-3 ztrans-py-1 ztrans-text-xs ztrans-text-gray-700 hover:ztrans-bg-gray-50"
							>
								{p.name}
							</button>
						))}
					</div>
				</div>
			)}

			<div className="ztrans-grid ztrans-grid-cols-2 ztrans-gap-4">
				<Field label={__('Code', 'zentranslate')} hint={__('e.g. en, es, pt-br', 'zentranslate')}>
					<TextInput value={values.code} onChange={set('code')} required disabled={!!initial} />
				</Field>
				<Field label={__('Locale', 'zentranslate')} hint={__('WP locale: en_US, es_ES, pt_BR', 'zentranslate')}>
					<TextInput value={values.locale} onChange={set('locale')} required />
				</Field>
				<Field label={__('Name (English)', 'zentranslate')}>
					<TextInput value={values.name} onChange={set('name')} required />
				</Field>
				<Field label={__('Native name', 'zentranslate')}>
					<TextInput value={values.native_name} onChange={set('native_name')} />
				</Field>
				<Field label={__('Flag code', 'zentranslate')} hint={__('Country code, e.g. ES, FR', 'zentranslate')}>
					<TextInput value={values.flag} onChange={set('flag')} />
				</Field>
				<Field label={__('Position', 'zentranslate')} hint={__('Sort order in the switcher', 'zentranslate')}>
					<TextInput type="number" value={values.position} onChange={set('position')} />
				</Field>
			</div>

			<div className="ztrans-flex ztrans-flex-col ztrans-gap-2">
				<Checkbox label={__('Right-to-left script', 'zentranslate')} checked={values.is_rtl} onChange={set('is_rtl')} />
				<Checkbox label={__('Active (shown in switcher)', 'zentranslate')} checked={values.active} onChange={set('active')} />
			</div>

			<Field
				label={__('Countries where this is the default language', 'zentranslate')}
				hint={__('ISO 3166-1 alpha-2 codes (e.g. MX, ES, AR). Used for country-based auto-redirect.', 'zentranslate')}
			>
				<div className="ztrans-flex ztrans-flex-wrap ztrans-items-center ztrans-gap-2">
					{values.country_codes.map((c) => (
						<span
							key={c}
							className="ztrans-inline-flex ztrans-items-center ztrans-gap-1 ztrans-rounded-full ztrans-bg-gray-100 ztrans-px-2 ztrans-py-0.5 ztrans-text-xs ztrans-text-gray-700"
						>
							{c}
							<button
								type="button"
								onClick={() => removeCountry(c)}
								className="ztrans-bare ztrans-text-gray-500 hover:ztrans-text-red-600"
								aria-label={__('Remove', 'zentranslate')}
							>
								×
							</button>
						</span>
					))}
					<TextInput
						value={countryDraft}
						maxLength={2}
						placeholder={__('e.g. MX', 'zentranslate')}
						onChange={(e) => setCountryDraft(e.target.value)}
						onKeyDown={(e) => {
							if (e.key === 'Enter') {
								e.preventDefault();
								addCountry();
							}
						}}
						style={{ width: '6rem' }}
					/>
					<Button type="button" variant="ghost" size="sm" onClick={addCountry}>
						{__('Add', 'zentranslate')}
					</Button>
				</div>
			</Field>

			<div className="ztrans-flex ztrans-justify-end ztrans-gap-2">
				<Button variant="ghost" type="button" onClick={onCancel}>{__('Cancel', 'zentranslate')}</Button>
				<Button type="submit" loading={busy}>
					{initial ? __('Save changes', 'zentranslate') : __('Add language', 'zentranslate')}
				</Button>
			</div>
		</form>
	);
}
